//! CM65/66 reduced joint decoder after Lean 1bb564d8 and 8d788115.
//! Every unknown raw-class coordinate remains free. Anchored entries are
//! generated by the proved affine map; numerical solvers are audited, not
//! asserted to refine Lean's exact-real minimizer theorem.
pub use dense::{Record, Result, Work, ce};
use serde::{Deserialize, Serialize};
pub const MAX_BYTES: u128 = 96_000_000_000;
pub const PROCESS_BYTES: u64 = 110_000_000_000;
pub mod domain;
pub mod head;
pub mod persistence;
pub mod projection;
pub mod resources;
#[cfg(test)]
mod tests;
pub mod training;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Shape {
    pub programs: usize,
    pub states: usize,
    pub classes: usize,
}
impl Shape {
    pub fn validate(self) -> Result<()> {
        if !(1..=1_000_000).contains(&self.programs)
            || !(4..=4096).contains(&self.states)
            || !self.states.is_multiple_of(4)
            || !(2..=1024).contains(&self.classes)
        {
            return Err("invalid reduced decoder shape".into());
        }
        Ok(())
    }
    pub fn rows(self) -> usize {
        self.programs * self.states
    }
    pub fn cells(self) -> usize {
        self.rows() * self.classes
    }
    pub fn admit(self, records: usize, unknown: usize, head_columns: usize) -> Result<u64> {
        self.validate()?;
        if records > 65536 || unknown > self.rows() || head_columns > self.cells() / 4 {
            return Err("invalid reduced allocation counts".into());
        }
        let parameters = self.programs as u128 + unknown as u128 * self.classes as u128;
        // Includes current/gradient/target/projection/sort/codec buffers,
        // four sparse heads, original encoded records, domain indices,
        // arbitrary-precision query scratch and 2 GiB runtime slack.
        let bytes = 16 * parameters * 8
            + 4 * (72 * head_columns as u128 + 96 * (self.rows() / 4) as u128)
            + 48 * self.rows() as u128
            + 64 * self.programs as u128
            + records as u128 * (8 * self.programs as u128 + 64)
            + 2 * 1024u128.pow(3);
        if bytes > MAX_BYTES {
            return Err("reduced buffers exceed 96 GB before allocation".into());
        }
        Ok(bytes as u64)
    }
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Parameters {
    /// All shared masses followed by every unknown row in state order.
    pub values: Vec<f64>,
}
impl Parameters {
    pub fn validate(&self, domain: &domain::Domain) -> Result<()> {
        if self.values.len() != domain.parameters()
            || self.values.iter().any(|x| !x.is_finite() || x.abs() > 1e12)
        {
            return Err("invalid reduced parameter tensor".into());
        }
        Ok(())
    }
    pub fn gamma(&self, domain: &domain::Domain, p: usize, s: usize, c: usize) -> f64 {
        let row = p * domain.shape.states + s;
        match domain.labels[row] {
            Some(y) => {
                if c == y {
                    self.values[p]
                } else {
                    0.
                }
            }
            None => self.values[domain.offsets[row] + c],
        }
    }
}
